    bidderId: bid.bidder_id
  }
}];

function analyzeBid(bid, auction) {
  const bidAmount = parseFloat(bid.amount);
  const currentBid = parseFloat(auction.current_bid);
  const minIncrement = currentBid * 0.05; // 5% minimum

  return {
    amount: bidAmount,
    isAboveMinimum: bidAmount >= (currentBid + minIncrement),
    percentageIncrease: ((bidAmount - currentBid) / currentBid) * 100,
    timestamp: bid.timestamp
  };
}

