// Process auction completion (sold or expired)
const auctionData = $input.first().json;
const auction = auctionData.auction;
const buyerId = auctionData.buyerId;
const isSold = auction.status === 'sold';

console.log(`Auction ${auction.id} ${isSold ? 'sold' : 'expired'}`);

// Process payment and item transfer
if (isSold && buyerId) {
  await processPayment(auction.seller_id, buyerId, auction.current_bid, 'auction');
  await transferItems(auction.seller_id, buyerId, auction.item_id, auction.quantity);

  // Update reputation
  await updateReputation(auction.seller_id, 'successful_sale');
  await updateReputation(buyerId, 'successful_purchase');
}

// Update market data
await updateMarketData(auction);

// Generate completion report
const completionReport = {
  auctionId: auction.id,
  sellerId: auction.seller_id,
  buyerId: buyerId,
  finalPrice: isSold ? auction.current_bid : null,
  status: auction.status,
  totalBids: auction.bid_count,
  duration: calculateAuctionDuration(auction.start_time, auction.end_time),
  isSold: isSold
};

// Send notifications
await sendCompletionNotifications(completionReport);

return [{
  json: {
    event: 'auction_completed',
    report: completionReport
  }
}];

